"use strict";
const $=id=>document.getElementById(id), C=window.GAME_CONFIG||{}, MAX_PLAYERS=6;
const COLORS=["金","青","赤","緑","紫","橙"], AI_NAMES=["つばさ商事","みらい工業","北星会社"];
const MARKETS=[
 {id:"sapporo",name:"札幌市場",buy:12,cap:20,demand:4},
 {id:"sendai",name:"仙台市場",buy:12,cap:20,demand:4},
 {id:"tokyo",name:"東京市場",buy:16,cap:32,demand:10},
 {id:"nagoya",name:"名古屋市場",buy:13,cap:24,demand:6},
 {id:"osaka",name:"大阪市場",buy:15,cap:28,demand:8},
 {id:"fukuoka",name:"福岡市場",buy:13,cap:24,demand:6}
];
const RISKS=["theft","fire","breakdown","researchSuccess","consumer","workerQuit","adSuccess"];
let mode=null,myId=null,roomCode=null,state=null,online=null,selected=null,reportTab="summary",viewReportIndex=0,lastRiskKey="";

function makePlayer(name,ai=false,index=0){return{name,ai,color:COLORS[index],cash:C.initialCash||300,materials:0,wip:0,products:0,workers:1,salesmen:1,smallMachines:1,attachments:0,largeMachines:0,ads:0,research:0,insurance:0,pac:false,merch:false,marketResearch:false,loans:[],actions:0,blockSalesThrough:-1,finance:newFinance()}}
function newFinance(){return{sales:0,sold:0,materialPurchases:0,conversion:0,fixed:0,investment:0,openingInventory:0}}
function newGame(players,order,host,periods,turns){return{phase:"playing",period:1,settings:{periods,turns,decisionRate:C.decisionCardRate||.7},host,order,current:0,turn:{card:null,ruleAUsed:false},players,markets:MARKETS.map(m=>({...m,remaining:m.demand})),competition:null,reports:[],logs:[{text:"会社を設立し、第1期を開始しました。"}]}}
function nameValue(){return $("playerName").value.trim()||"社長"} function currentId(s=state){return s.order[s.current]} function me(){return state&&state.players[myId]} function market(id,s=state){return s.markets.find(m=>m.id===id)}
function productionCapacity(p){let a=[];for(let i=0;i<p.largeMachines;i++)a.push(4+(p.pac?1:0));for(let i=0;i<p.smallMachines;i++)a.push(1+(i<p.attachments?1:0)+(p.pac?1:0));return a.sort((x,y)=>y-x).slice(0,p.workers).reduce((x,y)=>x+y,0)}
function salesCapacity(p){return p.salesmen*2+Math.min(p.ads,p.salesmen*2)*2} function loanTotal(p){return(p.loans||[]).reduce((n,l)=>n+l.principal,0)}
function equipmentValue(p){return Math.round((p.smallMachines*C.smallMachineCost+p.attachments*C.attachmentCost+p.largeMachines*C.largeMachineCost)*C.machineBookValueRate)}
function inventoryValue(p){return p.materials*C.materialUnitValue+p.wip*C.wipUnitValue+p.products*C.inventoryUnitValue} function equity(p){return Math.round(p.cash+inventoryValue(p)+equipmentValue(p)-loanTotal(p))}
function log(s,text){s.logs.unshift({text,at:Date.now()});s.logs=s.logs.slice(0,100)} function esc(v){return String(v==null?"":v).replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]))}
function showScreen(id){["startScreen","lobbyScreen","gameScreen"].forEach(x=>$(x).hidden=x!==id)} function err(id,text){$(id).textContent=text||""}

$("soloBtn").onclick=()=>{mode="solo";myId="human";const ps={human:makePlayer(nameValue(),false,0)};AI_NAMES.forEach((n,i)=>ps["ai"+i]=makePlayer(n,true,i+1));state=newGame(ps,Object.keys(ps),myId,+$("periodSetting").value,+$("turnSetting").value);showScreen("gameScreen");render()};

async function firebase(){if(online)return online;if(!window.firebaseConfig||!firebaseConfig.apiKey||!firebaseConfig.databaseURL)throw Error("firebase-config.jsの設定が必要です。");const mods=await Promise.all([import("https://www.gstatic.com/firebasejs/10.14.1/firebase-app.js"),import("https://www.gstatic.com/firebasejs/10.14.1/firebase-auth.js"),import("https://www.gstatic.com/firebasejs/10.14.1/firebase-database.js")]);const app=mods[0].initializeApp(firebaseConfig),auth=mods[1].getAuth(app),cred=await mods[1].signInAnonymously(auth);online={db:mods[2].getDatabase(app),ref:mods[2].ref,set:mods[2].set,get:mods[2].get,onValue:mods[2].onValue,runTransaction:mods[2].runTransaction,uid:cred.user.uid};return online}
function code(){return Math.random().toString(36).slice(2,8).toUpperCase()}
$("createBtn").onclick=async()=>{try{err("startError","接続しています…");const f=await firebase();mode="online";myId=f.uid;roomCode=code();await f.set(f.ref(f.db,"rooms/"+roomCode),{phase:"lobby",host:myId,settings:{periods:+$("periodSetting").value,turns:+$("turnSetting").value},players:{[myId]:{name:nameValue(),color:COLORS[0]}}});watch();showScreen("lobbyScreen");err("startError","")}catch(e){err("startError",e.message)}};
$("joinBtn").onclick=async()=>{try{const c=$("roomCode").value.trim().toUpperCase();if(c.length!==6)throw Error("6文字のルームコードを入力してください。");const f=await firebase(),snap=await f.get(f.ref(f.db,"rooms/"+c));if(!snap.exists())throw Error("ルームが見つかりません。");const r=snap.val();if(r.phase!=="lobby")throw Error("ゲーム開始済みです。");if(Object.keys(r.players||{}).length>=MAX_PLAYERS)throw Error("満員です。");mode="online";myId=f.uid;roomCode=c;await f.set(f.ref(f.db,`rooms/${c}/players/${myId}`),{name:nameValue(),color:COLORS[Object.keys(r.players).length]});watch();showScreen("lobbyScreen")}catch(e){err("startError",e.message)}};
function watch(){online.onValue(online.ref(online.db,"rooms/"+roomCode),snap=>{if(!snap.exists()){location.reload();return}state=snap.val();if(state.phase==="lobby"){showScreen("lobbyScreen");renderLobby()}else{showScreen("gameScreen");render();remotePhases()}})}
function renderLobby(){const es=Object.entries(state.players||{});$("copyCode").textContent=roomCode;$("lobbySettings").textContent=`${state.settings.periods}期・各社${state.settings.turns}手・意思決定カード70%`;$("lobbyPlayers").innerHTML=es.map(([id,p])=>`<div><b>${esc(p.name)}</b><small>${id===state.host?" ホスト":" 参加者"}</small></div>`).join("");$("startGameBtn").hidden=myId!==state.host;$("startGameBtn").disabled=es.length<2;$("lobbyNote").textContent=`${es.length} / ${MAX_PLAYERS}人参加中`}
$("copyCode").onclick=()=>navigator.clipboard&&navigator.clipboard.writeText(roomCode);$("startGameBtn").onclick=()=>online.runTransaction(online.ref(online.db,"rooms/"+roomCode),r=>{if(!r||r.host!==myId||r.phase!=="lobby")return r;const order=Object.keys(r.players),ps={};order.forEach((id,i)=>ps[id]=makePlayer(r.players[id].name,false,i));return newGame(ps,order,myId,r.settings.periods,r.settings.turns)});

function render(){if(!state||state.phase==="lobby"||!me())return;const p=me(),active=currentId()===myId&&state.phase==="playing"&&!state.competition,drawn=!!state.turn.card;$("clock").textContent=`第${state.period}/${state.settings.periods}期・${Math.min(p.actions+1,state.settings.turns)}/${state.settings.turns}手`;$("myName").textContent=p.name;$("myCash").textContent=Math.round(p.cash)+"万円";
 const rs=[["材料",p.materials],["仕掛品",p.wip],["商品",p.products],["ワーカー",p.workers],["営業",p.salesmen],["小型機",p.smallMachines],["大型機",p.largeMachines],["借入",loanTotal(p)+"万"]];$("resources").innerHTML=rs.map(x=>`<div><span>${x[0]}</span><b>${x[1]}</b></div>`).join("");
 $("markets").innerHTML=state.markets.map(m=>`<article class="market"><h3>${m.name}</h3><p>市場残量 ${m.remaining}/${m.demand}</p><div class="track">${Array.from({length:m.demand},(_,i)=>`<i class="${i>=m.remaining?"off":""}"></i>`).join("")}</div><dl><dt>材料単価</dt><dd>${Math.max(1,m.buy-(p.merch?2:0))}万円</dd><dt>販売上限</dt><dd>${m.cap+(p.marketResearch?2:0)}万円</dd></dl></article>`).join("");
 const ranked=Object.entries(state.players).sort((a,b)=>equity(b[1])-equity(a[1]));$("companies").innerHTML=ranked.map(([id,q],i)=>`<div class="company-row"><header><b>${i+1}. ${esc(q.name)}${id===myId?"（自社）":""}</b><span>${q.actions}/${state.settings.turns}手</span></header><dl><div><dt>自己資本</dt><dd>${equity(q)}</dd></div><div><dt>商品</dt><dd>${q.products}</dd></div><div><dt>研究</dt><dd>${q.research}</dd></div></dl></div>`).join("");$("gameLog").innerHTML=(state.logs||[]).map(l=>`<li>${esc(l.text)}</li>`).join("");
 const cv=$("cardView");cv.className="card-view "+(state.turn.card||"");cv.innerHTML=state.turn.card==="decision"?"<span>DECISION CARD</span><b>意思決定カード</b><p>ルールAを1回使えます。ルールBも使用できます。</p>":state.turn.card==="risk"?`<span>RISK CARD</span><b>${esc(state.turn.riskName||"リスク発生")}</b><p>ルールBを使用してから手番を終了できます。</p>`:"<span>YOUR TURN</span><b>カードを引く</b><p>意思決定カード70%・リスクカード30%</p>";
 if(active&&state.turn.card==="risk"){const key=`${state.period}:${state.current}:${p.actions}:${state.turn.riskName}`;if(key!==lastRiskKey){lastRiskKey=key;$("riskTitle").textContent=state.turn.riskName;$("riskText").textContent=state.turn.riskText||"リスクが発生しました。";if(!$("riskDialog").open)$("riskDialog").showModal()}}
 $("drawCardBtn").hidden=!active||drawn;$("endTurnBtn").hidden=!active||!drawn;$("turnMessage").textContent=state.competition?"販売コンペの入札中です。":active?(drawn?"ルールを実行し、手番を終了してください。":"あなたの手番です。カードを引いてください。"):`${esc(state.players[currentId()]&&state.players[currentId()].name)}の手番です。`;
 const aEnabled=active&&state.turn.card==="decision"&&!state.turn.ruleAUsed;document.querySelectorAll("[data-a]").forEach(b=>{const sellBlocked=b.dataset.a==="sell"&&p.actions<=p.blockSalesThrough;b.disabled=!aEnabled||sellBlocked;b.classList.toggle("locked",b.disabled)});const bEnabled=active&&drawn;document.querySelectorAll("[data-b]").forEach(b=>{const owned=(b.dataset.b==="pac"&&p.pac)||(b.dataset.b==="merch"&&p.merch)||(b.dataset.b==="marketResearch"&&p.marketResearch);b.disabled=!bEnabled||owned;b.classList.toggle("locked",b.disabled);b.classList.toggle("owned",owned);const note=b.querySelector("small");if(note){if(!note.dataset.default)note.dataset.default=note.textContent;note.textContent=owned?"取得済み":note.dataset.default}});$("reportsBtn").disabled=!(state.reports&&state.reports.length);$("news").textContent=(state.logs&&state.logs[0]&&state.logs[0].text)||"カードを引いてください。";
 if(mode==="solo"&&state.phase==="report")showReport(false);if(mode==="solo"&&state.phase==="finished")showReport(true)
}

$("drawCardBtn").onclick=()=>mutate(s=>{if(currentId(s)!==myId||s.turn.card)return s;drawCard(s,myId);return s});
function drawCard(s,id){const isDecision=Math.random()<s.settings.decisionRate;s.turn={card:isDecision?"decision":"risk",ruleAUsed:false};if(isDecision)log(s,`${s.players[id].name}が意思決定カードを引きました。`);else{const type=RISKS[Math.floor(Math.random()*RISKS.length)];const r=applyRisk(s,id,type);s.turn.riskName=r.title;s.turn.riskText=r.text;log(s,`${s.players[id].name}：${r.title}―${r.text}`)}}
function applyRisk(s,id,type){const p=s.players[id];if(type==="theft"){const n=Math.min(p.products,1+Math.floor(Math.random()*3));p.products-=n;let extra="";if(p.insurance>0){p.insurance--;p.cash+=10;extra=" 保険金10万円を受領。"}return{title:"盗難",text:`商品を${n}個失いました。${extra}`}}
 if(type==="fire"){const n=p.materials;p.materials=0;let extra="";if(p.insurance>0){p.insurance--;p.cash+=8;extra=" 保険金8万円を受領。"}return{title:"火災",text:`材料${n}個をすべて失いました。${extra}`}}
 if(type==="breakdown"){const n=Math.min(p.wip,1+Math.floor(Math.random()*3));p.wip-=n;return{title:"故障",text:`仕掛品を${n}個失いました。`}}
 if(type==="consumer"){p.blockSalesThrough=p.actions+1;return{title:"消費者運動",text:"次の自分の手番まで販売できません。"}}
 if(type==="workerQuit"){const n=p.workers>0?1:0;p.workers-=n;return{title:"ワーカー退職",text:n?"ワーカーが1人退職しました。":"退職するワーカーはいませんでした。"}}
 if(type==="researchSuccess")return exclusiveSale(s,p,Math.min(p.products,p.research),"研究開発成功");return exclusiveSale(s,p,Math.min(p.products,p.ads*2),"広告成功")}
function exclusiveSale(s,p,qty,title){if(qty<=0)return{title,text:"対象チップまたは商品がなく、販売は発生しませんでした。"};const ms=s.markets.filter(m=>m.remaining>0).sort((a,b)=>b.cap-a.cap);if(!ms.length)return{title,text:"市場需要が残っていませんでした。"};const m=ms[0],q=Math.min(qty,m.remaining),price=Math.max(1,m.cap-1);p.products-=q;p.cash+=q*price;p.finance.sales+=q*price;p.finance.sold+=q;m.remaining-=q;return{title,text:`${m.name}へ${q}個を${price}万円で独占販売しました（ストッカー行）。`}}

document.querySelectorAll("[data-a]").forEach(b=>b.onclick=()=>openRuleA(b.dataset.a));document.querySelectorAll("[data-b]").forEach(b=>b.onclick=()=>openRuleB(b.dataset.b));
function openDialog(title,help,html,kind,payload={}){selected={kind,payload};$("actionKicker").textContent=kind==="A"?"RULE A":"RULE B";$("actionTitle").textContent=title;$("actionHelp").textContent=help;$("actionBody").innerHTML=html;err("actionError","");$("actionDialog").showModal()}
function closeActionDialog(){selected=null;err("actionError","");if($("actionDialog").open)$("actionDialog").close("cancel")}
function marketRows(kind){return`<div class="market-plan">${state.markets.map(m=>`<div class="dynamic-row"><span>${m.name}<small>${kind==="buy"?` 単価${Math.max(1,m.buy-(me().merch?2:0))}万・残${m.remaining}`:` 上限${m.cap+(me().marketResearch?2:0)}万・残${m.remaining}`}</small></span><input type="number" min="0" max="${m.remaining}" value="0" data-market="${m.id}" data-value="qty">${kind==="sell"?`<input type="number" min="1" max="${m.cap+(me().marketResearch?2:0)}" value="${m.cap}" data-market="${m.id}" data-value="price">`:""}</div>`).join("")}</div>`}
function openRuleA(a){if(a==="buy")openDialog("材料購入","複数市場から同時に購入できます。",marketRows("buy"),"A",{a});
 else if(a==="machine")openDialog("設備投資","設備を1つ選択します。小型機1台につきアタッチメントは1つまでです。",`<div class="machine-options"><label><input type="radio" name="machine" value="small" checked> 小型機械（${C.smallMachineCost}万円）</label><label><input type="radio" name="machine" value="attachment"> アタッチメント（${C.attachmentCost}万円）</label><label><input type="radio" name="machine" value="large"> 大型機械（${C.largeMachineCost}万円）</label></div>`,"A",{a});
 else if(a==="production")openDialog("投入／完成",`現在の生産能力は${productionCapacity(me())}個です。投入と完成をそれぞれ能力まで実行できます。`,`<label>投入数（材料→仕掛品）<input id="inputQty" type="number" min="0" max="${productionCapacity(me())}" value="0"></label><label>完成数（仕掛品→商品）<input id="completeQty" type="number" min="0" max="${productionCapacity(me())}" value="0"></label><p>投入費 ${C.inputCost}万円/個・完成費 ${C.completionCost}万円/個</p>`,"A",{a});
 else if(a==="hire")openDialog("採用",`会社都合では退職させられません。採用費は1人${C.workerHireCost}万円です。`,`<label>職種<select id="hireType"><option value="worker">ワーカー</option><option value="salesman">セールスマン</option></select></label><label>人数<input id="hireQty" type="number" min="1" max="3" value="1"></label>`,"A",{a});
 else if(a==="ad")openDialog("広告チップ",`1ターンに何枚でも購入可能。1枚${C.adChipCost}万円で販売能力が2個増え、セールスマン1人につき2枚まで有効です。`,`<label>購入枚数<input id="adQty" type="number" min="1" max="20" value="1"></label>`,"A",{a});
 else if(a==="research")openDialog("研究開発",`1ターンに1枚だけ購入できます。1枚${C.researchCost}万円で価格競争力が2増えます。`,`<p>研究開発チップを1枚購入します。</p>`,"A",{a});else if(a==="sell")openParentSale()}
function openRuleB(b){const p=me();if((b==="pac"&&p.pac)||(b==="merch"&&p.merch)||(b==="marketResearch"&&p.marketResearch))return;if(b==="insurance")openDialog("保険","火災・盗難で保険金を受け取るとチップを1枚返却します。",`<label>購入枚数<input id="bQty" type="number" min="1" max="10" value="1"></label>`,"B",{b});
 else if(b==="pac")openDialog("PAC生産性","稼働する機械1台につき生産能力が1増えます。",`<p>PACチップを取得します。</p>`,"B",{b});else if(b==="merch")openDialog("マーチャンダイザー","材料を市場価格より2万円安く購入できます。",`<p>マーチャンダイザーを取得します。</p>`,"B",{b});else if(b==="marketResearch")openDialog("マーケットリサーチ","販売価格上限より2万円高く入札できます。",`<p>マーケットリサーチを取得します。</p>`,"B",{b});
 else if(b==="relocate")openDialog("配置転換","ワーカーとセールスマンを1人ずつ配置転換できます。",`<label>変更<select id="relocateType"><option value="w2s">ワーカー → セールスマン</option><option value="s2w">セールスマン → ワーカー</option></select></label>`,"B",{b});
 else if(b==="sellMachine")openDialog("機械売却","購入価格の1/2で売却します。",`<label>設備<select id="sellMachineType"><option value="small">小型機械</option><option value="attachment">アタッチメント</option><option value="large">大型機械</option></select></label>`,"B",{b});
 else if(b==="borrow"){const n=Math.min((p.loans||[]).length,2),rate=[15,10,5][n],mult=[2,3,4][n],limit=Math.max(0,equity(p)*mult-loanTotal(p));openDialog("銀行借入",`今回の金利${rate}%・総借入限度${mult}倍（追加可能 ${Math.floor(limit)}万円）`,`<label>借入額<input id="loanAmount" type="number" min="1" max="${Math.floor(limit)}" value="${Math.min(30,Math.floor(limit))}"></label>`,"B",{b,rate,limit});}
 else if(b==="repay")openDialog("借金返済","金利の高い借入から返済します。",`<label>返済額<input id="repayAmount" type="number" min="1" max="${Math.min(Math.floor(p.cash),loanTotal(p))}" value="${Math.min(30,Math.floor(p.cash),loanTotal(p))}"></label>`,"B",{b})}

$("actionForm").onsubmit=e=>{e.preventDefault();if(!selected)return;const action=selected,x=collectAction(),problem=validate(action,x);if(problem){err("actionError",problem);return}$("actionDialog").close("execute");selected=null;mutate(s=>{const p=s.players[myId];applySelected(s,p,action,x);if(action.kind==="A")s.turn.ruleAUsed=true;return s})};
function collectAction(){const x={};if(selected.payload.a==="buy"){x.plan={};document.querySelectorAll("[data-value=qty]").forEach(i=>x.plan[i.dataset.market]=+i.value||0)}if(selected.payload.a==="machine")x.type=document.querySelector("input[name=machine]:checked").value;if(selected.payload.a==="production"){x.input=+$('inputQty').value||0;x.complete=+$('completeQty').value||0}if(selected.payload.a==="hire"){x.type=$("hireType").value;x.qty=+$("hireQty").value}if(selected.payload.a==="ad")x.qty=+$("adQty").value;if(selected.payload.b==="insurance")x.qty=+$("bQty").value;if(selected.payload.b==="relocate")x.type=$("relocateType").value;if(selected.payload.b==="sellMachine")x.type=$("sellMachineType").value;if(selected.payload.b==="borrow")x.amount=+$("loanAmount").value;if(selected.payload.b==="repay")x.amount=+$("repayAmount").value;return x}
function actionCost(p,sel,x){const a=sel.payload.a,b=sel.payload.b;if(a==="buy")return Object.entries(x.plan).reduce((n,[id,q])=>n+q*Math.max(1,market(id).buy-(p.merch?2:0)),0);if(a==="machine")return x.type==="small"?C.smallMachineCost:x.type==="large"?C.largeMachineCost:C.attachmentCost;if(a==="production")return x.input*C.inputCost+x.complete*C.completionCost;if(a==="hire")return x.qty*(x.type==="worker"?C.workerHireCost:C.salesmanHireCost);if(a==="ad")return x.qty*C.adChipCost;if(a==="research")return C.researchCost;if(b==="insurance")return x.qty*C.insuranceCost;if(b==="pac")return C.pacCost;if(b==="merch")return C.merchandiserCost;if(b==="marketResearch")return C.marketResearchCost;if(b==="relocate")return C.relocationCost;return 0}
function validate(sel,x){const p=me(),a=sel.payload.a,b=sel.payload.b,cost=actionCost(p,sel,x);if(cost>p.cash)return"現金が不足しています。";if(a==="buy"){if(!Object.values(x.plan).some(Boolean))return"購入数を入力してください。";for(const[id,q]of Object.entries(x.plan)){const m=market(id);if(q<0||q>m.remaining)return`${m.name}の市場残量を超えています。`}}if(a==="machine"&&x.type==="attachment"&&p.attachments>=p.smallMachines)return"アタッチメントを装着できる小型機械がありません。";if(a==="production"){const cap=productionCapacity(p);if(x.input>cap||x.complete>cap)return"生産能力を超えています。";if(x.input>p.materials)return"材料が不足しています。";if(x.complete>p.wip+x.input)return"仕掛品が不足しています。";if(!x.input&&!x.complete)return"投入数または完成数を入力してください。"}if(a==="research"&&p.research<0)return"購入できません。";if(b==="pac"&&p.pac)return"すでに取得済みです。";if(b==="merch"&&p.merch)return"すでに取得済みです。";if(b==="marketResearch"&&p.marketResearch)return"すでに取得済みです。";if(b==="relocate"&&((x.type==="w2s"&&p.workers<1)||(x.type==="s2w"&&p.salesmen<1)))return"配置転換できる人員がいません。";if(b==="sellMachine"&&((x.type==="small"&&p.smallMachines<1)||(x.type==="large"&&p.largeMachines<1)||(x.type==="attachment"&&p.attachments<1)))return"売却できる設備がありません。";if(b==="borrow"&&(x.amount<1||x.amount>sel.payload.limit))return"借入限度を確認してください。";if(b==="repay"&&(x.amount<1||x.amount>p.cash||x.amount>loanTotal(p)))return"返済額を確認してください。";return""}
function applySelected(s,p,sel,x){const a=sel.payload.a,b=sel.payload.b,cost=actionCost(p,sel,x);p.cash-=cost;if(a==="buy"){let total=0;Object.entries(x.plan).forEach(([id,q])=>{p.materials+=q;market(id,s).remaining-=q;total+=q});p.finance.materialPurchases+=cost;log(s,`${p.name}が複数市場から材料を${total}個購入。`)}else if(a==="machine"){if(x.type==="small")p.smallMachines++;if(x.type==="large")p.largeMachines++;if(x.type==="attachment")p.attachments++;p.finance.investment+=cost;log(s,`${p.name}が設備投資を実行。`)}else if(a==="production"){p.materials-=x.input;p.wip+=x.input-x.complete;p.products+=x.complete;p.finance.conversion+=cost;log(s,`${p.name}が${x.input}個投入・${x.complete}個完成。`)}else if(a==="hire"){if(x.type==="worker")p.workers+=x.qty;else p.salesmen+=x.qty;p.finance.fixed+=cost;log(s,`${p.name}が${x.type==="worker"?"ワーカー":"セールスマン"}を${x.qty}人採用。`)}else if(a==="ad"){p.ads+=x.qty;p.finance.fixed+=cost;log(s,`${p.name}が広告チップを${x.qty}枚購入。`)}else if(a==="research"){p.research++;p.finance.fixed+=cost;log(s,`${p.name}が研究開発チップを1枚購入。`)}else if(b==="insurance"){p.insurance+=x.qty;p.finance.fixed+=cost;log(s,`${p.name}が保険チップを${x.qty}枚購入。`)}else if(b==="pac"){p.pac=true;p.finance.fixed+=cost;log(s,`${p.name}がPAC生産性を取得。`)}else if(b==="merch"){p.merch=true;p.finance.fixed+=cost;log(s,`${p.name}がマーチャンダイザーを取得。`)}else if(b==="marketResearch"){p.marketResearch=true;p.finance.fixed+=cost;log(s,`${p.name}がマーケットリサーチを取得。`)}else if(b==="relocate"){if(x.type==="w2s"){p.workers--;p.salesmen++}else{p.salesmen--;p.workers++}p.finance.fixed+=cost;log(s,`${p.name}が配置転換を実施。`)}else if(b==="sellMachine"){const price=(x.type==="small"?C.smallMachineCost:x.type==="large"?C.largeMachineCost:C.attachmentCost)/2;if(x.type==="small"){p.smallMachines--;if(p.attachments>p.smallMachines){p.attachments--;p.cash+=C.attachmentCost/2}}if(x.type==="large")p.largeMachines--;if(x.type==="attachment")p.attachments--;p.cash+=price;log(s,`${p.name}が設備を${price}万円で売却。`)}else if(b==="borrow"){p.cash+=x.amount;p.loans.push({principal:x.amount,rate:sel.payload.rate});log(s,`${p.name}が金利${sel.payload.rate}%で${x.amount}万円を借入。`)}else if(b==="repay"){let left=x.amount;p.cash-=x.amount;p.loans.sort((u,v)=>v.rate-u.rate).forEach(l=>{const q=Math.min(left,l.principal);l.principal-=q;left-=q});p.loans=p.loans.filter(l=>l.principal>0);log(s,`${p.name}が借入金を${x.amount}万円返済。`)}}

function openParentSale(){const p=me();if(!p.products){alert("販売できる商品がありません。");return}const cap=salesCapacity(p);selected={kind:"sale-parent"};$("saleTitle").textContent="親として販売コンペを開始";$("saleHelp").textContent=`販売能力は合計${cap}個です。複数市場へ提示できます。`;$("saleBody").innerHTML=marketRows("sell");$("declineSale").textContent="キャンセル";$("saleClose").hidden=false;err("saleError","");$("saleDialog").showModal()}
function collectOffers(){const offers={};state.markets.forEach(m=>{const q=document.querySelector(`[data-market="${m.id}"][data-value="qty"]`),pr=document.querySelector(`[data-market="${m.id}"][data-value="price"]`);if(q&&+q.value>0)offers[m.id]={qty:+q.value,price:+pr.value}});return offers}
$("saleForm").onsubmit=e=>{e.preventDefault();const offers=collectOffers(),p=me(),total=Object.values(offers).reduce((n,o)=>n+o.qty,0);if(!Object.keys(offers).length){err("saleError","市場と数量を入力してください。");return}if(total>p.products||total>salesCapacity(p)){err("saleError","商品数または販売能力を超えています。");return}for(const[id,o]of Object.entries(offers)){const m=market(id),limit=m.cap+(p.marketResearch?2:0);if(o.price>limit){err("saleError",`${m.name}の価格上限は${limit}万円です。`);return}}
 if(selected.kind==="sale-parent"){startSale(offers);$("saleDialog").close()}else submitChildSale(offers)};
$("declineSale").onclick=()=>selected&&selected.kind==="sale-child"?submitChildSale({}):closeSaleDialog();
function closeSaleDialog(){selected=null;err("saleError","");if($("saleDialog").open)$("saleDialog").close("cancel")}
function startSale(offers){if(mode==="solo"){const bids={[myId]:{offers}};state.order.filter(id=>id!==myId).forEach(id=>bids[id]={offers:aiChildOffers(state.players[id],offers)});resolveSale(state,{parent:myId,offers,bids});state.turn.ruleAUsed=true;render();return}mutate(s=>{if(currentId(s)!==myId||s.turn.ruleAUsed)return s;const bids={[myId]:{offers}};s.order.forEach(id=>{if(id!==myId&&(!s.players[id].products||salesCapacity(s.players[id])<1))bids[id]={offers:{}}});s.competition={parent:myId,offers,bids};return s})}
function openChildSale(){const comp=state.competition,p=me(),cap=salesCapacity(p);selected={kind:"sale-child"};$("saleTitle").textContent="子として販売コンペに参加";$("saleHelp").textContent=`親が提示した市場だけに、各市場で親の数量以下・合計${cap}個まで入札できます。`;$("saleBody").innerHTML=`<div class="market-plan">${Object.entries(comp.offers).map(([id,o])=>{const m=market(id),limit=m.cap+(p.marketResearch?2:0);return`<div class="dynamic-row"><span>${m.name}<small> 親${o.qty}個</small></span><input type="number" min="0" max="${Math.min(o.qty,p.products,cap)}" value="0" data-market="${id}" data-value="qty"><input type="number" min="1" max="${limit}" value="${Math.min(o.price,limit)}" data-market="${id}" data-value="price"></div>`}).join("")}</div>`;$("declineSale").textContent="辞退";$("saleClose").hidden=true;err("saleError","");if(!$("saleDialog").open)$("saleDialog").showModal()}
function submitChildSale(offers){const p=me(),total=Object.values(offers).reduce((n,o)=>n+o.qty,0);if(total>p.products||total>salesCapacity(p)){err("saleError","商品数または販売能力を超えています。");return}if(mode==="online")mutate(s=>{if(s.competition&&!s.competition.bids[myId])s.competition.bids[myId]={offers};return s});$("saleDialog").close()}
function aiChildOffers(p,parentOffers){if(!p.products)return{};let left=Math.min(p.products,salesCapacity(p)),out={};Object.entries(parentOffers).forEach(([id,o])=>{if(left<1)return;const m=market(id),q=Math.min(left,o.qty,1+Math.floor(Math.random()*2));out[id]={qty:q,price:Math.max(1,Math.min(m.cap,o.price+(Math.floor(Math.random()*5)-2)))};left-=q});return out}
function resolveSale(s,comp){Object.keys(comp.offers).forEach(mid=>{const m=market(mid,s);let demand=m.remaining;const bids=Object.entries(comp.bids).map(([id,b])=>({id,offer:b.offers&&b.offers[mid]})).filter(x=>x.offer&&x.offer.qty>0).sort((x,y)=>{const px=s.players[x.id],py=s.players[y.id],ex=x.offer.price-px.research*2-(x.id===comp.parent?2:0),ey=y.offer.price-py.research*2-(y.id===comp.parent?2:0);return ex-ey||py.research-px.research||(Math.random()-.5)});const sold=[];bids.forEach(x=>{const p=s.players[x.id],q=Math.min(demand,x.offer.qty,p.products);if(!q)return;p.products-=q;p.cash+=q*x.offer.price;p.finance.sales+=q*x.offer.price;p.finance.sold+=q;demand-=q;sold.push(`${p.name}${q}個@${x.offer.price}`)});m.remaining=demand;log(s,`${m.name}販売：${sold.join("、")||"不成立"}`)});s.players[comp.parent].actions=s.players[comp.parent].actions;s.turn.ruleAUsed=true;s.competition=null}

$("endTurnBtn").onclick=()=>{if(mode==="solo"){endTurn(state,myId);runAiTurns();render()}else mutate(s=>{if(currentId(s)===myId&&!s.competition)endTurn(s,myId);return s})};
function endTurn(s,id){s.players[id].actions++;if(Object.values(s.players).every(p=>p.actions>=s.settings.turns)){settlePeriod(s);return}let n=s.current;do{n=(n+1)%s.order.length}while(s.players[s.order[n]].actions>=s.settings.turns);s.current=n;s.turn={card:null,ruleAUsed:false}}
function runAiTurns(){if(state.phase!=="playing")return;state.order.filter(id=>id!==myId).forEach(id=>{if(state.players[id].actions>=state.settings.turns)return;state.current=state.order.indexOf(id);drawCard(state,id);if(state.turn.card==="decision")aiDecision(state,id);endTurn(state,id)});if(state.phase==="playing"){state.current=state.order.indexOf(myId);state.turn={card:null,ruleAUsed:false}}}
function aiDecision(s,id){const p=s.players[id];if(p.products>0&&p.actions>1){const ms=s.markets.filter(m=>m.remaining>0).slice(0,2),offers={};let left=Math.min(p.products,salesCapacity(p));ms.forEach(m=>{if(left){const q=Math.min(left,2);offers[m.id]={qty:q,price:Math.max(1,m.cap-Math.floor(Math.random()*4))};left-=q}});const bids={[id]:{offers}};s.order.filter(x=>x!==id&&x!==myId).forEach(x=>bids[x]={offers:aiChildOffers(s.players[x],offers)});resolveSale(s,{parent:id,offers,bids});return}if(p.wip>0||p.materials>0){const cap=productionCapacity(p),complete=Math.min(p.wip,cap),input=Math.min(p.materials,cap);const cost=complete*C.completionCost+input*C.inputCost;if(cost<=p.cash)applySelected(s,p,{payload:{a:"production"}},{input,complete});else log(s,`${p.name}は意思決定を見送り。`);return}const m=[...s.markets].filter(x=>x.remaining>0).sort((a,b)=>a.buy-b.buy)[0];if(!m){log(s,`${p.name}は意思決定を見送り。`);return}const q=Math.min(3,m.remaining,Math.floor(p.cash/m.buy));if(q)applySelected(s,p,{payload:{a:"buy"}},{plan:{[m.id]:q}});else log(s,`${p.name}は意思決定を見送り。`)}

function settlePeriod(s){const rows={};Object.entries(s.players).forEach(([id,p])=>{const interest=(p.loans||[]).reduce((n,l)=>n+l.principal*l.rate/100,0),wages=p.workers*C.workerSalary+p.salesmen*C.salesmanSalary,holding=p.products,closing=inventoryValue(p),variable=Math.max(0,p.finance.openingInventory+p.finance.materialPurchases+p.finance.conversion-closing),fixed=p.finance.fixed+wages+holding+interest,valueAdded=p.finance.sales-variable,profit=valueAdded-fixed,avgP=p.finance.sold?p.finance.sales/p.finance.sold:0,vUnit=p.finance.sold?variable/p.finance.sold:0,margin=avgP-vUnit,bepQ=margin>0?fixed/margin:0,bepSales=avgP*bepQ;p.cash-=wages+holding+interest;if(p.cash<0){const q=Math.ceil(-p.cash/10)*10;p.cash+=q;p.loans.push({principal:q,rate:15})}const assets=p.cash+closing+equipmentValue(p),liabilities=loanTotal(p),capital=assets-liabilities;rows[id]={name:p.name,sales:p.finance.sales,sold:p.finance.sold,variable,fixed,valueAdded,profit,avgP,vUnit,margin,bepQ,bepSales,cash:p.cash,inventory:closing,equipment:equipmentValue(p),assets,liabilities,equity:capital,interest,wages};});s.reports.push({period:s.period,rows});s.phase=s.period>=s.settings.periods?"finished":"report";s.competition=null;log(s,`第${s.period}期の決算が完了しました。`)}
function nextPeriod(s){s.period++;s.current=0;s.turn={card:null,ruleAUsed:false};s.markets=MARKETS.map(m=>({...m,remaining:m.demand}));Object.values(s.players).forEach(p=>{p.actions=0;p.finance=newFinance();p.finance.openingInventory=inventoryValue(p)});s.phase="playing";log(s,`第${s.period}期を開始しました。`)}

function mutate(fn){if(mode==="solo"){state=fn(state)||state;render();return Promise.resolve()}return online.runTransaction(online.ref(online.db,"rooms/"+roomCode),s=>fn(s)||s)}
function remotePhases(){if(state.competition&&!state.competition.bids[myId]&&me().products>0)openChildSale();if(mode==="online"&&myId===state.host&&state.competition&&Object.keys(state.competition.bids||{}).length===state.order.length)mutate(s=>{if(s.competition){const parent=s.competition.parent;resolveSale(s,s.competition);s.players[parent].actions=s.players[parent].actions}return s});if(state.phase==="report")showReport(false);if(state.phase==="finished")showReport(true);if(state.phase==="playing"&&$("reportDialog").open&&!$("reportsBtn").dataset.manual)$("reportDialog").close()}

function showReport(final,manual=false){if(!state.reports||!state.reports.length)return;viewReportIndex=manual?state.reports.length-1:state.reports.length-1;$("reportPeriod").innerHTML=state.reports.map((r,i)=>`<option value="${i}" ${i===viewReportIndex?"selected":""}>第${r.period}期</option>`).join("");$("reportTitle").textContent=final?"最終決算":manual?"決算履歴":`第${state.reports[viewReportIndex].period}期 決算`;$("reportNext").hidden=manual;$("reportClose").hidden=!manual;$("reportNext").textContent=final?"最終順位を見る":mode==="online"&&myId!==state.host?"ホストが進めるのを待つ":"次の期へ";$("reportNext").disabled=!final&&mode==="online"&&myId!==state.host;reportTab="summary";renderReport();$("reportsBtn").dataset.manual=manual?"1":"";if(!$("reportDialog").open)$("reportDialog").showModal()}
function renderReport(){const rep=state.reports[viewReportIndex],r=rep.rows[myId];document.querySelectorAll("[data-tab]").forEach(b=>b.classList.toggle("active",b.dataset.tab===reportTab));if(reportTab==="rank"){$("reportBody").innerHTML=Object.entries(rep.rows).sort((a,b)=>b[1].equity-a[1].equity).map(([id,x],i)=>`<div class="rank-row"><b>${i+1}</b><span>${esc(x.name)}${id===myId?"（自社）":""}</span><b>${Math.round(x.equity)}万円</b></div>`).join("");return}if(reportTab==="summary"){$("reportBody").innerHTML=`<div class="metric-grid">${[["平均販売単価",r.avgP],["変動単価",r.vUnit],["単位付加価値",r.margin],["付加価値総額",r.valueAdded],["損益分岐点数量",r.bepQ],["損益分岐点売上",r.bepSales]].map(x=>`<div class="metric"><span>${x[0]}</span><b>${Number(x[1]).toFixed(1)}${x[0].includes("数量")?"個":"万円"}</b></div>`).join("")}</div>`;return}if(reportTab==="pl"){$("reportBody").innerHTML=`<table><tr><td>売上高</td><td>${r.sales.toFixed(1)}</td></tr><tr><td>変動費</td><td>${r.variable.toFixed(1)}</td></tr><tr><td>付加価値</td><td>${r.valueAdded.toFixed(1)}</td></tr><tr><td>固定費</td><td>${r.fixed.toFixed(1)}</td></tr><tr><td>うち人件費</td><td>${r.wages.toFixed(1)}</td></tr><tr><td>うち金利</td><td>${r.interest.toFixed(1)}</td></tr><tr class="total"><td>利益</td><td>${r.profit.toFixed(1)}</td></tr></table>`;return}$("reportBody").innerHTML=`<table><tr><td>現金</td><td>${r.cash.toFixed(1)}</td></tr><tr><td>棚卸資産</td><td>${r.inventory.toFixed(1)}</td></tr><tr><td>設備</td><td>${r.equipment.toFixed(1)}</td></tr><tr class="total"><td>資産合計</td><td>${r.assets.toFixed(1)}</td></tr><tr><td>借入金</td><td>${r.liabilities.toFixed(1)}</td></tr><tr class="total"><td>自己資本</td><td>${r.equity.toFixed(1)}</td></tr></table>`}
document.querySelectorAll("[data-tab]").forEach(b=>b.onclick=()=>{reportTab=b.dataset.tab;renderReport()});$("reportPeriod").onchange=()=>{viewReportIndex=+$("reportPeriod").value;renderReport()};$("reportsBtn").onclick=()=>showReport(false,true);$("reportClose").onclick=()=>{$("reportsBtn").dataset.manual="";$("reportDialog").close()};$("reportNext").onclick=()=>{if(state.phase==="finished"){$("reportDialog").close();showFinal();return}if(mode==="solo"){nextPeriod(state);$("reportDialog").close();render()}else if(myId===state.host)mutate(s=>{if(s.phase==="report")nextPeriod(s);return s}).then(()=>$("reportDialog").close())};
function showFinal(){const rep=state.reports[state.reports.length-1];$("finalBody").innerHTML=Object.entries(rep.rows).sort((a,b)=>b[1].equity-a[1].equity).map(([id,r],i)=>`<div class="rank-row"><b>${i+1}</b><span>${esc(r.name)}${id===myId?"（自社）":""}</span><b>${Math.round(r.equity)}万円</b></div>`).join("");$("finalDialog").showModal()}

$("actionCancel").onclick=closeActionDialog;$("actionClose").onclick=closeActionDialog;$("actionDialog").addEventListener("cancel",()=>{selected=null;err("actionError","")});$("saleClose").onclick=()=>selected&&selected.kind==="sale-child"?null:closeSaleDialog();$("saleDialog").addEventListener("cancel",e=>{if(selected&&selected.kind==="sale-child")e.preventDefault();else selected=null});
$("rulesBtn").onclick=()=>$("rulesDialog").showModal();document.querySelectorAll("[data-close]").forEach(b=>b.onclick=()=>$(b.dataset.close).close());$("resetBtn").onclick=()=>{if(confirm("ゲームから退出しますか？"))location.reload()};$("againBtn").onclick=()=>location.reload();$("riskClose").onclick=()=>$("riskDialog").close();
window.addEventListener("error",e=>{const box=$("startError");if(box&&!state)box.textContent="読み込みエラー: "+e.message});
